/**
 * Cross-language beacon vectors, shared with pytest.
 *
 * `tests/vectors/beacon_vectors.json` is generated by the Python side
 * (`python -m puffer.beacon.vectors`, libsodium signing with a fixed seed).
 * Agreement on this file is what proves the browser verifier and
 * `puffer.beacon` implement the same format and the same error codes.
 */
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import { type BeaconError, verifyChain, verifyPulse } from '../src/lib/beacon.ts';
import { array, beaconPulse, nullable, object, string } from '../src/lib/protocol.ts';

const VECTORS_PATH = fileURLToPath(new URL('../../tests/vectors/beacon_vectors.json', import.meta.url));

const vectorFile = object({
  public_key: string,
  valid_chain: array(beaconPulse),
  invalid: array(
    object({
      name: string,
      pulse: beaconPulse,
      prev: nullable(beaconPulse),
      expected_error: string,
    }),
  ),
});

const present = existsSync(VECTORS_PATH);

describe('cross-language beacon vectors', () => {
  if (!present) {
    it.skip(`skipped: ${VECTORS_PATH} not found - generate it with \`python -m puffer.beacon.vectors\``, () => {});
    return;
  }

  const vectors = vectorFile(JSON.parse(readFileSync(VECTORS_PATH, 'utf8')));

  it('has a non-trivial chain and invalid cases', () => {
    expect(vectors.valid_chain.length).toBeGreaterThan(1);
    expect(vectors.invalid.length).toBeGreaterThan(0);
  });

  it('verifies the valid chain with the pinned key', () => {
    const result = verifyChain(vectors.valid_chain, { publicKey: vectors.public_key });
    expect(result.firstFailure).toBeNull();
    expect(result.valid).toBe(true);
  });

  it.each(vectors.invalid.map((v) => [v.name, v] as const))('rejects %s', (_name, vector) => {
    const result = verifyPulse(vector.pulse, { prev: vector.prev, publicKey: vectors.public_key });
    expect(result.valid).toBe(false);
    expect(result.error).toBe(vector.expected_error as BeaconError);
  });
});
